                </div>
                <div className="flex flex-col">
                  <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">Official Email</span>
                  <span className="text-lg font-medium">agencigrowofficial@gmail.com</span>
                </div>
              </div>
            </div>
          </div>

          <div className="flex-1 relative z-10">
            <form onSubmit={handleSubmit} className="bg-white rounded-3xl p-6 md:p-10 space-y-6 shadow-2xl">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-xs font-bold text-[#1F2933] uppercase mb-2 tracking-wider">Full Name</label>
                  <input 
                    required
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    placeholder="Jane Doe"
                    className="w-full px-5 py-4 rounded-xl bg-[#F7F8FA] border border-[#E5E7EB] text-[#1F2933] focus:outline-none focus:border-[#00D094] focus:ring-1 focus:ring-[#00D094] transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-[#1F2933] uppercase mb-2 tracking-wider">Work Email</label>
                  <input 
                    required
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    placeholder="jane@company.com"
                    className="w-full px-5 py-4 rounded-xl bg-[#F7F8FA] border border-[#E5E7EB] text-[#1F2933] focus:outline-none focus:border-[#00D094] focus:ring-1 focus:ring-[#00D094] transition-all"
                  />
                </div>
