                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-[#1F2933] uppercase mb-2 tracking-wider">Your Message</label>
                <textarea 
                  required
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  rows={4}
                  placeholder="Tell us about your brand goals..."
                  className="w-full px-5 py-4 rounded-xl bg-[#F7F8FA] border border-[#E5E7EB] text-[#1F2933] focus:outline-none focus:border-[#00D094] focus:ring-1 focus:ring-[#00D094] transition-all resize-none"
