import React, { useState, useEffect } from 'react';
import { Send, CheckCircle, AlertCircle, Loader2 } from 'lucide-react';
import emailjs from '@emailjs/browser';

const SERVICE_ID = 'service_bhp5uad';
const TEMPLATE_ID = 'template_imbvi0n';
const PUBLIC_KEY = 'hskHvipGSlSKBgJaE';

const ContactForm: React.FC = () => {
  const [status, setStatus] = useState<'idle' | 'sending' | 'success' | 'error'>('idle');
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    company: '',
    message: ''
  });

  useEffect(() => {
    emailjs.init(PUBLIC_KEY);
  }, []);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    setFormData(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('sending');

    const templateParams = {
      name: formData.name,
      email: formData.email,
      company: formData.company,
      message: formData.message,
    };

    try {
      const response = await emailjs.send(
        SERVICE_ID,
        TEMPLATE_ID,
        templateParams,
        PUBLIC_KEY
      );

      if (response.status === 200) {
        setStatus('success');
        setFormData({ name: '', email: '', company: '', message: '' });
      } else {
        throw new Error(`EmailJS returned status ${response.status}`);
      }
    } catch (err) {
      console.error('EmailJS detailed error:', err);
      setStatus('error');
    }
  };

  if (status === 'success') {
    return (
      <section id="contact" className="py-24 bg-white text-center scroll-mt-20">
        <div className="max-w-xl mx-auto px-4">
          <div className="w-20 h-20 bg-[#C9ADA7]/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <CheckCircle className="text-[#C9ADA7] w-10 h-10" />
          </div>
          <h2 className="text-3xl font-bold text-[#22223B] mb-4">Message sent successfully!</h2>
          <p className="text-[#4A4E69] mb-8 text-lg">We’ll get back to you within 24 hours at the email provided.</p>
          <button 
            onClick={() => setStatus('idle')}
            className="px-8 py-3 bg-[#22223B] text-white rounded-xl font-bold hover:bg-[#C9ADA7] transition-all"
          >
            Send Another Message
          </button>
        </div>
      </section>
    );
  }

  return (
    <section id="contact" className="py-24 bg-white scroll-mt-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="bg-[#22223B] rounded-[40px] p-8 md:p-16 flex flex-col lg:flex-row gap-12 text-white overflow-hidden relative border border-[#4A4E69]/20 shadow-2xl">
          <div className="flex-1 relative z-10">
            <h2 className="text-4xl md:text-5xl font-extrabold mb-8 tracking-tight">
              Let's build your <br/>
              <span style={{ color: '#C9ADA7' }}>growth engine.</span>
            </h2>
            <p className="text-[#9A8C98] text-lg mb-10 leading-relaxed max-w-md">
              Have a specific question or custom requirement? Send us a direct message and our strategy team will reach out shortly.
            </p>
            <div className="space-y-6">
              <div className="flex items-center gap-4 group">
                <div className="w-12 h-12 bg-white/5 rounded-2xl flex items-center justify-center group-hover:bg-[#C9ADA7] transition-colors">
                  <Send className="w-5 h-5 text-[#C9ADA7] group-hover:text-white" />
                </div>
                <div className="flex flex-col">
                  <span className="text-xs font-bold text-[#9A8C98] uppercase tracking-widest">Official Email</span>
                  <span className="text-lg font-medium">agencigrowofficial@gmail.com</span>
                </div>
              </div>
            </div>
          </div>

          <div className="flex-1 relative z-10">
            <form onSubmit={handleSubmit} className="bg-white rounded-3xl p-6 md:p-10 space-y-6 shadow-2xl">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-xs font-bold text-[#22223B] uppercase mb-2 tracking-wider">Full Name</label>
                  <input 
                    required
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    placeholder="Jane Doe"
                    className="w-full px-5 py-4 rounded-xl bg-[#F2E9E4]/30 border border-[#F2E9E4] text-[#22223B] focus:outline-none focus:border-[#C9ADA7] focus:ring-1 focus:ring-[#C9ADA7] transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-[#22223B] uppercase mb-2 tracking-wider">Work Email</label>
                  <input 
                    required
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    placeholder="jane@company.com"
                    className="w-full px-5 py-4 rounded-xl bg-[#F2E9E4]/30 border border-[#F2E9E4] text-[#22223B] focus:outline-none focus:border-[#C9ADA7] focus:ring-1 focus:ring-[#C9ADA7] transition-all"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-[#22223B] uppercase mb-2 tracking-wider">Company Name</label>
                <input 
                  required
                  type="text"
                  name="company"
                  value={formData.company}
                  onChange={handleChange}
                  placeholder="Acme Corp"
                  className="w-full px-5 py-4 rounded-xl bg-[#F2E9E4]/30 border border-[#F2E9E4] text-[#22223B] focus:outline-none focus:border-[#C9ADA7] focus:ring-1 focus:ring-[#C9ADA7] transition-all"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-[#22223B] uppercase mb-2 tracking-wider">Your Message</label>
                <textarea 
                  required
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  rows={4}
                  placeholder="Tell us about your brand goals..."
                  className="w-full px-5 py-4 rounded-xl bg-[#F2E9E4]/30 border border-[#F2E9E4] text-[#22223B] focus:outline-none focus:border-[#C9ADA7] focus:ring-1 focus:ring-[#C9ADA7] transition-all resize-none"
                ></textarea>
              </div>

              {status === 'error' && (
                <div className="flex items-center gap-2 text-red-500 bg-red-50 p-4 rounded-xl border border-red-100">
                  <AlertCircle className="w-5 h-5" />
                  <span className="text-sm font-medium">Failed to send. Please try again or email us directly.</span>
                </div>
              )}

              <button 
                type="submit"
                disabled={status === 'sending'}
                className="w-full py-5 bg-[#22223B] text-white rounded-xl font-bold text-lg hover:bg-[#C9ADA7] disabled:bg-[#9A8C98] disabled:cursor-not-allowed transition-all transform hover:scale-[1.02] flex items-center justify-center gap-3 shadow-xl"
              >
                {status === 'sending' ? (
                  <>
                    <Loader2 className="w-5 h-5 animate-spin" />
                    Sending...
                  </>
                ) : (
                  <>
                    Send Message
                    <Send className="w-5 h-5" />
                  </>
                )}
              </button>
            </form>
          </div>
          {/* Background decoration */}
          <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-[#C9ADA7]/5 rounded-full -translate-y-1/2 translate-x-1/2 blur-[100px] pointer-events-none"></div>
        </div>
      </div>
    </section>
  );
};

