import React, { useState, useEffect } from 'react';
import { Send, CheckCircle, AlertCircle, Loader2 } from 'lucide-react';
import emailjs from '@emailjs/browser';
import { motion } from 'framer-motion';

const SERVICE_ID = 'service_bhp5uad';
const TEMPLATE_ID = 'template_imbvi0n';
const PUBLIC_KEY = 'hskHvipGSlSKBgJaE';

const ContactForm: React.FC = () => {
  const [status, setStatus] = useState<'idle' | 'sending' | 'success' | 'error'>('idle');
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    company: '',
    message: ''
  });

  useEffect(() => {
    emailjs.init(PUBLIC_KEY);
  }, []);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('sending');
    try {
      const response = await emailjs.send(SERVICE_ID, TEMPLATE_ID, formData, PUBLIC_KEY);
      if (response.status === 200) {
        setStatus('success');
        setFormData({ name: '', email: '', company: '', message: '' });
      }
    } catch (err) {
      setStatus('error');
    }
  };

  if (status === 'success') {
    return (
      <section id="contact" className="py-32 bg-[#283618] text-center scroll-mt-24">
        <div className="max-w-xl mx-auto px-6">
          <div className="w-24 h-24 bg-[#2ECC71]/10 rounded-full flex items-center justify-center mx-auto mb-10">
            <CheckCircle className="text-[#2ECC71] w-12 h-12" />
          </div>
          <h2 className="text-4xl font-black text-white mb-6">Message Sent.</h2>
          <p className="text-[#FEFAE0]/70 mb-12 text-xl font-light">We'll respond within 24 hours.</p>
          <button 
            onClick={() => setStatus('idle')}
            className="px-12 py-5 bg-[#2ECC71] text-[#283618] rounded-sm font-black uppercase tracking-widest hover:bg-white transition-all"
          >
            Send Another
          </button>
        </div>
      </section>
    );
  }

  return (
    <section id="contact" className="py-32 bg-white scroll-mt-24">
      <div className="max-w-7xl mx-auto px-6 lg:px-12">
        <div className="bg-[#283618] rounded-[50px] p-10 md:p-20 flex flex-col lg:flex-row gap-20 text-white overflow-hidden relative shadow-2xl">
          <div className="flex-1 relative z-10">
            <motion.h2 
